#include "stdafx.h"#include <rsuStr.h>int _Kstricmp( const char * dst, const char * src ){    int f, l;  do  {    f = (unsigned char)(*(dst++));    l = (unsigned char)(*(src++));    if( (f >= 'A') && (f <= 'Z') )      f -= 'A' - 'a';    else if( (f >= 'А') && (f <= 'Я') )      f -= 'А' - 'я';    if( (l >= 'A') && (l <= 'Z') )      l -= 'A' - 'a';    else if( (l >= 'А') && (l <= 'Я') )      l -= 'А' - 'я';  }  while ( f && (f == l) );  return(f - l);}int _Kstrnicmp ( const char * first, const char * last, size_t count ){  if(count)  {    int f=0;    int l=0;    do    {      f = (unsigned char)(*(first++));      if ( (f >= 'A') &&  (f <= 'Z') )        f -= 'A' - 'a';      else if( (f >= 'А') && (f <= 'Я') )        f -= 'А' - 'я';      l = (unsigned char)(*(last++));      if ( (l >= 'A') &&  (l <= 'Z') )        l -= 'A' - 'a';      else if( (l >= 'А') && (l <= 'Я') )        l -= 'А' - 'я';    }    while ( --count && f && (f == l) );    return ( f - l );  }  else  {    return 0;  }}char _Ktoupper( char src ){  unsigned char l = (unsigned char)src;  if ( (l >= 'a') &&  (l <= 'z') )    l += 'A' - 'a';  else if( (l >= 'а') && (l <= 'я') )    l += 'А' - 'я';  return (char)l;}void _Ktoupper( LPSTR src ){  for( LPSTR p = src; *p; ++p )    *p = _Ktoupper( *p );}